-- Aggregate field coverage only; no source values are returned.
with stats as (
    select object_construct(
        'source_record_id', object_construct('populated', count(source_record_id), 'blank', count_if(trim(source_record_id::varchar) = '')),
        'person_id', object_construct('populated', count(person_id), 'blank', count_if(trim(person_id::varchar) = '')),
        'sk_patient_id', object_construct('populated', count(sk_patient_id), 'blank', count_if(trim(sk_patient_id::varchar) = '')),
        'patient_id', object_construct('populated', count(patient_id), 'blank', count_if(trim(patient_id::varchar) = '')),
        'encounter_id', object_construct('populated', count(encounter_id), 'blank', count_if(trim(encounter_id::varchar) = '')),
        'practitioner_id', object_construct('populated', count(practitioner_id), 'blank', count_if(trim(practitioner_id::varchar) = '')),
        'unique_booking_reference_number', object_construct('populated', count(unique_booking_reference_number), 'blank', count_if(trim(unique_booking_reference_number::varchar) = '')),
        'clinical_effective_date', object_construct('populated', count(clinical_effective_date), 'blank', count_if(trim(clinical_effective_date::varchar) = '')),
        'date_recorded', object_construct('populated', count(date_recorded), 'blank', count_if(trim(date_recorded::varchar) = '')),
        'mode', object_construct('populated', count(mode), 'blank', count_if(trim(mode::varchar) = '')),
