        'referring_organisation_code', object_construct('populated', count(referring_organisation_code), 'blank', count_if(trim(referring_organisation_code::varchar) = '')),
        'referring_organisation_code_authority', object_construct('populated', count(referring_organisation_code_authority), 'blank', count_if(trim(referring_organisation_code_authority::varchar) = '')),
        'referring_organisation_name', object_construct('populated', count(referring_organisation_name), 'blank', count_if(trim(referring_organisation_name::varchar) = '')),
        'receiving_organisation_id', object_construct('populated', count(receiving_organisation_id), 'blank', count_if(trim(receiving_organisation_id::varchar) = '')),
        'receiving_organisation_code', object_construct('populated', count(receiving_organisation_code), 'blank', count_if(trim(receiving_organisation_code::varchar) = '')),
        'receiving_organisation_code_authority', object_construct('populated', count(receiving_organisation_code_authority), 'blank', count_if(trim(receiving_organisation_code_authority::varchar) = '')),
        'receiving_organisation_name', object_construct('populated', count(receiving_organisation_name), 'blank', count_if(trim(receiving_organisation_name::varchar) = '')),
        'publisher_organisation_id', object_construct('populated', count(publisher_organisation_id), 'blank', count_if(trim(publisher_organisation_id::varchar) = '')),
        'publisher_organisation_code', object_construct('populated', count(publisher_organisation_code), 'blank', count_if(trim(publisher_organisation_code::varchar) = '')),
        'publisher_organisation_code_authority', object_construct('populated', count(publisher_organisation_code_authority), 'blank', count_if(trim(publisher_organisation_code_authority::varchar) = '')),
        'publisher_organisation_name', object_construct('populated', count(publisher_organisation_name), 'blank', count_if(trim(publisher_organisation_name::varchar) = '')),
        'source_publisher_organisation_code', object_construct('populated', count(source_publisher_organisation_code), 'blank', count_if(trim(source_publisher_organisation_code::varchar) = '')),
        'referral_request_source_concept_id', object_construct('populated', count(referral_request_source_concept_id), 'blank', count_if(trim(referral_request_source_concept_id::varchar) = '')),
        'referral_code', object_construct('populated', count(referral_code), 'blank', count_if(trim(referral_code::varchar) = '')),
        'referral_name', object_construct('populated', count(referral_name), 'blank', count_if(trim(referral_name::varchar) = '')),
        'referral_coding_system', object_construct('populated', count(referral_coding_system), 'blank', count_if(trim(referral_coding_system::varchar) = '')),
        'mapped_concept_code', object_construct('populated', count(mapped_concept_code), 'blank', count_if(trim(mapped_concept_code::varchar) = '')),
